 [[8,420,'meera'],[8,1020,'tara'],[9,480,'rohan'],[10,540,'aditya'],[12,420,'meera'],[13,480,'rohan'],[13,960,'tara']].forEach(([d,t,s])=>S.lessons.push({id:'l'+(uid++),student:s,coach:'arjun',d,t,dur:60,status:'confirmed',price:3000,pkg:'one'}));
 [[7,1020],[14,1020],[21,1020],[7,420],[11,480],[12,540],[14,420],[15,1020],[16,480],[17,540],[18,420],[19,1020],[20,480],[21,540],[22,420],[23,1080],[25,480],[27,420]].forEach(([d,t])=>{if(!clashAt(d,t,60))S.open.add(d+':'+t)});
 Object.assign(S,{sv:{},autoRegular:false,calW:0,prefs:null,dp:{},mq:0,view:'list',sort:'best',mapSel:null,locI:0,loc:LOCS[0],locLabel:null,radius:10,who:'kabir',swings:[]});
